$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=Split-Path $PSScriptRoot -Parent
foreach($chapter in @(1,3)){
 $z=[IO.Compression.ZipFile]::Open((Join-Path $root "Chapter $chapter.docx"),'Update')
 try{
  $entry=$z.GetEntry('word/document.xml');$r=[IO.StreamReader]::new($entry.Open());try{[xml]$d=$r.ReadToEnd()}finally{$r.Dispose()}
  $n=[Xml.XmlNamespaceManager]::new($d.NameTable);$n.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main');$body=$d.SelectSingleNode('//w:body',$n)
  function Txt($p){($p.SelectNodes('.//w:t',$n)|ForEach-Object InnerText)-join ''}
  function Put($p,$text){$ts=@($p.SelectNodes('.//w:t',$n));$ts[0].InnerText=$text;foreach($v in @($ts|Select-Object -Skip 1)){$v.InnerText=''}}
  foreach($p in $body.SelectNodes('w:p',$n)){
   $t=(Txt $p).Trim()
   if($chapter -eq 1 -and $t.StartsWith('Dashboard sessions and attendance-scanner sessions were tracked separately.')){Put $p 'Dashboard sessions and attendance-scanner sessions are tracked separately. Ordinary session replacement affects the corresponding scope. Administrator trusted-browser transfer is an additional security operation: successful replacement of that trust revokes both previous dashboard and scanner scopes. Online pages check session ownership about every five seconds; suspended or offline pages check when they resume or reconnect. The thirty-day phone-pairing period concerns the camera connection and is separate from administrator browser trust and operator authentication.'}
   if($chapter -eq 3 -and $t.StartsWith('Usernames and email addresses are checked')){Put $p 'Usernames and email addresses are checked for duplicates without regard to capitalization or surrounding spaces. Registration shows availability feedback and rejects identifiers already in use; server checks support this validation. Dashboard and attendance-scanner sessions are tracked as separate scopes. Ordinary replacement affects its own scope, while successful administrator trusted-browser transfer explicitly revokes both old scopes. Online pages check ownership about every five seconds and return to sign-in when replaced; offline or suspended pages check on resumption or reconnection. Trust transfer and explicit forget-device revocation are additional administrator security controls, not ordinary scope-only replacement.'}
   if($chapter -eq 1 -and $t.StartsWith('Authentication.')){Put $p 'Authentication. Verification of an account through Supabase Auth and the applicable administrator device-security checks before protected IronGrind access is authorized.'}
  }
  if($chapter -eq 1 -and -not (@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).StartsWith('Trusted Browser.')})).Count){
   $anchor=@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).StartsWith('User Session.')})[0]
   foreach($text in @('Trusted Browser. A browser profile and site origin whose public signing key is registered for an administrator account for the configured thirty-day trust period. Its private key remains in browser storage; this does not identify physical hardware.','Time-Based One-Time Password (TOTP). A short-lived code generated by an enrolled authenticator, used for administrator browser registration, replacement and the implemented recovery verification path.','Device Approval. An in-website decision by an eligible active trusted administrator session on another browser login request. Approval must be followed by fresh TOTP and successful device proof before trust is transferred.')){
    $p=$anchor.CloneNode($true);foreach($v in @($p.SelectNodes('.//w:bookmarkStart|.//w:bookmarkEnd',$n))){$null=$v.ParentNode.RemoveChild($v)};Put $p $text;$null=$body.InsertAfter($p,$anchor);$anchor=$p
   }
  }
  if($chapter -eq 3){
   $purpose=@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).StartsWith('Stores the active dashboard and attendance-scanner sessions.')})
   $table20=@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).Trim() -eq 'Table 20: private.account_sessions'})[0].NextSibling
   while($table20 -and $table20.LocalName -ne 'tbl'){$table20=$table20.NextSibling}
   if($purpose.Count -ne 1 -or -not $table20){throw 'Account session purpose anchor ambiguous'}
   $null=$body.InsertAfter($purpose[0],$table20)
   foreach($p in $d.SelectNodes('//w:tbl//w:p',$n)){
    if((Txt $p).Trim() -eq 'Authenticate administrators, staff, and members and enforce role-based access.') {Put $p 'Authenticate administrators, staff and members; enforce role-based access. Administrator login additionally verifies trusted-browser proof, TOTP registration/replacement and eligible current-session approval before activating protected access.'}
   }
  }
  $stream=$entry.Open();$stream.SetLength(0);$writer=[IO.StreamWriter]::new($stream,[Text.UTF8Encoding]::new($false));try{$d.Save($writer)}finally{$writer.Dispose()}
 }finally{$z.Dispose()}
}
'Aligned session-transfer exceptions, operational terms and login requirement; kept the original account-session table purpose together.'
